39|// One short caption per panel: the first clause of the scene summary,
40|// cut at a word boundary to 90 chars with an ellipsis when longer.
41|export const PANEL_CAPTION_MAX = 90;
42|
43|export function panelCaption(summary: string): string {
44|  const clean = summary.replace(/\s+/g, " ").trim();
45|  if (clean.length <= PANEL_CAPTION_MAX) return clean;
46|  const end = clean.search(/[.!?;]["'”’)\]]?\s/);
47|  const first = end > 0 && end < PANEL_CAPTION_MAX ? clean.slice(0, end + 1) : null;
48|  if (first) return first;
49|  const cut = clean.slice(0, PANEL_CAPTION_MAX - 1);
50|  return `${cut.slice(0, Math.max(1, cut.lastIndexOf(" "))).trimEnd()}…`;
51|}
