29|export async function handleImagesPost(req: Request): Promise<Response> {
30|  const capped = await readBodyCapped(req, MAX_IMAGE_BODY_BYTES);
31|  if (!capped.ok) {
32|    return Response.json(
33|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
34|      { status: capped.reason === "too_large" ? 413 : 400 },
35|    );
36|  }
37|
38|  let parsed: ImageRequest;
39|  try {
40|    parsed = parseImageRequest(JSON.parse(capped.text));
41|  } catch (e) {
42|    if (e instanceof ImageStyleError) {
43|      return Response.json(
44|        { status: "error", code: "bad_request", message: MSG_STYLE } satisfies ImageResponse,
45|        { status: 400 },
46|      );
47|    }
48|    return Response.json(
49|      { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
50|      { status: 400 },
51|    );
52|  }
53|
54|  let env;
55|  try {
56|    env = readImageEnv();
57|  } catch (e) {
58|    const message = e instanceof Error ? e.message : "";
59|    const prefix = "missing image env:";
60|    const names = message.startsWith(prefix) ? message.slice(prefix.length).trim() : "";
61|    console.warn(`image env missing: ${names}`);
62|    return Response.json(
63|      { status: "error", code: "unavailable", message: MSG_UNAVAILABLE } satisfies ImageResponse,
64|      { status: 503 },
65|    );
66|  }
67|
68|  try {
69|    const { book, scenes } = loadOzBook();
70|    try {
71|      validateAgainstBook(
72|        parsed,
73|        {
74|          id: book.id,
75|          textVersion: book.textVersion,
76|          paragraphNs: new Set(book.paragraphs.map((p) => p.n)),
77|          sceneIds: new Set(scenes.map((s) => s.id)),
78|        },
79|      );
80|    } catch {
81|      return Response.json(
82|        { status: "error", code: "bad_request", message: MSG_BAD_REQUEST } satisfies ImageResponse,
83|        { status: 400 },
84|      );
85|    }
86|
87|    const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
88|    const sceneOf = scenes.find((s) =>
89|      parsed.kind === "passage" ? parsed.n >= s.start_n && parsed.n <= s.end_n : s.id === parsed.sceneId,
90|    );
91|    const sceneParas = sceneOf
92|      ? book.paragraphs.filter((p) => p.n >= sceneOf.start_n && p.n <= sceneOf.end_n)
93|      : [];
94|    const content: ImageContent = {
95|      passageText: parsed.kind === "passage" ? (byN.get(parsed.n) ?? "") : "",
96|      sceneTitle: sceneOf?.title ?? "",
97|      sceneClip: sceneParas.map((p) => p.text).join(" "),
98|    };
99|
100|    const cookieValue = parseAnonCookie(req.headers.get("cookie"));
101|    let anonId = cookieValue ? verifyAnonCookie(cookieValue, env.sessionSecret) : null;
102|    let setCookie: string | null = null;
103|    if (!anonId) {
104|      const issued = issueAnonId(env.sessionSecret);
105|      anonId = issued.id;
106|      setCookie = serializeAnonCookie(issued.value);
107|    }
108|
109|    const res = await orchestrate(parsed, {
110|      kv: createRestKV(env.upstashUrl, env.upstashToken),
111|      store: createBlobStore(),
112|      generate: createMetaClient(env.metaKey),
113|      env,
114|      content,
115|      ip: clientIp(req.headers.get("x-forwarded-for")),
116|      anonId,
117|      day: utcDay(),
118|    });
119|
120|    const { json, status } = toResponse(res);
121|    const headers = setCookie ? { "Set-Cookie": setCookie } : undefined;
122|    return Response.json(json, { status, headers });
123|  } catch (e) {
124|    console.error(`image request failed: ${errorTag(e)}`);
125|    return Response.json(
126|      { status: "error", code: "unavailable", message: MSG_UNAVAILABLE } satisfies ImageResponse,
127|      { status: 503 },
128|    );
129|  }
