38|      if (event.key === "Escape") {
39|        // The shared lightbox sits above the modal and closes itself.
40|        if (document.querySelector(".lightbox")) return;
41|        event.stopPropagation();
42|        onClose();
43|        return;
44|      }
45|      if (event.key !== "Tab" || !boxRef.current) return;
