57|export function PictureDraw({ skin, frozen }: { skin: PictureSkin; frozen?: boolean }) {
58|  const reducedMotion = useReducedMotion();
59|  // Frozen (or reduced motion) renders the static still: no timers, no
60|  // rAF, so the drawing stops the instant the card turns ready.
61|  const stillMode = frozen || reducedMotion;
62|  const uid = useId().replace(/[^a-zA-Z0-9]/g, "");
63|  const grainId = `pdg${uid}`;
64|  const softId = `pds${uid}`;
65|  const toolRef = useRef<SVGGElement | null>(null);
66|  const pathRefs = useRef<(SVGPathElement | null)[]>([]);
67|  // Passes accumulate: outline first, then shading depth on top. When
68|  // the base passes run out, further light layers keep appending, so
69|  // the tool keeps working but nothing already drawn is ever wiped.
70|  const [strokes, setStrokes] = useState<FlatStroke[]>(() =>
71|    [0, 1, 2, 3].flatMap((l) => strokesForSkin(skin, l)),
72|  );
73|  const nextLayer = useRef(4);
74|  useEffect(() => {
75|    nextLayer.current = 4;
76|    setStrokes([0, 1, 2, 3].flatMap((l) => strokesForSkin(skin, l)));
77|  }, [skin]);
78|  const strokesRef = useRef(strokes);
79|  strokesRef.current = strokes;
80|  const stillAll = useMemo(() => stillStrokes(skin), [skin]);
81|  const still = stillMode ? stillAll : null;
82|  const flat = still ?? strokes;
83|
84|  useEffect(() => {
85|    if (stillMode) return;
86|    const paths = pathRefs.current;
87|    const tool = toolRef.current;
88|    let dead = false;
89|    let frame = 0;
90|    const pos = { x: 340, y: 304 };
91|    const place = (x: number, y: number) => {
92|      pos.x = x;
93|      pos.y = y;
94|      tool?.setAttribute("transform", `translate(${x.toFixed(1)} ${y.toFixed(1)})`);
95|    };
96|    place(pos.x, pos.y);
97|
98|    const pointAt = (p: SVGPathElement, f: number): { x: number; y: number } | null => {
99|      try {
100|        if (typeof p.getPointAtLength !== "function" || typeof p.getTotalLength !== "function") return null;
101|        const pt = p.getPointAtLength(p.getTotalLength() * f);
102|        return { x: pt.x, y: pt.y };
103|      } catch {
104|        return null;
105|      }
106|    };
107|
108|    // Draw every stroke once, in order, and keep it: outline first,
109|    // then shading layers on top. Past the base passes, further light
110|    // layers append so the tool keeps working without ever wiping.
111|    let i = 0;
112|    const stepStroke = () => {
113|      if (dead) return;
114|      if (i >= strokesRef.current.length) {
115|        const layer = strokesForSkin(skin, nextLayer.current);
116|        nextLayer.current += 1;
117|        setStrokes((prev) => [...prev, ...layer]);
118|        let waits = 0;
119|        const poll = () => {
120|          if (dead) return;
121|          if ((pathRefs.current.length > i && pathRefs.current[i]) || waits++ > 120) stepStroke();
122|          else frame = requestAnimationFrame(poll);
123|        };
124|        frame = requestAnimationFrame(poll);
125|        return;
126|      }
127|      const el = paths[i];
128|      const spec = strokesRef.current[i];
129|      i += 1;
