35|export function BookView({
36|  model,
37|  initialSceneId,
38|  panelsByChapter,
39|}: {
40|  model: ReaderModel;
41|  initialSceneId: string;
42|  panelsByChapter: { ch: number; panels: ChapterPanel[] }[];
43|}) {
44|  const [storedPref, setStoredPref] = useState<ImageStylePref | null>(null);
45|  // Server render uses the default so hydration matches; the live skin
46|  // applies on mount via useSyncExternalStore.
47|  const skin = useSkin();
48|  const pref = effectiveImageStylePref(storedPref, skin);
49|  const [currentId, setCurrentId] = useState(initialSceneId);
50|  const [panelsCh, setPanelsCh] = useState<number | null>(null);
51|  const readColRef = useRef<HTMLDivElement | null>(null);
52|  const figEls = useRef(new Map<string, HTMLElement>());
53|  const pic = usePictures({ bookId: model.bookId, textVersion: model.textVersion, sceneId: currentId, pref });
54|  const order = useMemo(() => model.chapters.flatMap((c) => c.scenes.map((s) => s.id)), [model]);
55|  const sceneOf = useMemo(() => {
56|    const map = new Map<string, { ch: number; k: number; n: number; chapterTitle: string }>();
57|    for (const chapter of model.chapters) {
58|      chapter.scenes.forEach((s, i) => {
59|        map.set(s.id, { ch: chapter.ch, k: i + 1, n: chapter.scenes.length, chapterTitle: chapter.title });
60|      });
61|    }
62|    return map;
63|  }, [model]);
64|  const panelsOf = useMemo(() => new Map(panelsByChapter.map((e) => [e.ch, e.panels])), [panelsByChapter]);
65|  const titles = useMemo(() => new Map(model.chapters.map((c) => [c.ch, c.title])), [model]);
66|  const info = sceneOf.get(currentId);
67|  const bookIndex = order.indexOf(currentId);
68|  const lastChapter = model.chapters[model.chapters.length - 1]?.ch ?? 0;
69|
70|  // One commit path for every scene change: state, the live store the
71|  // music container reads, and the deep-link URL. No router pushes, so
72|  // scrolling never remounts.
73|  const commitScene = useCallback((id: string) => {
74|    setCurrentId((prev) => (prev === id ? prev : id));
75|    setCurrentSceneId(id);
76|    window.history.replaceState(null, "", `/leer/${id}`);
77|  }, []);
78|
79|  // Land on the deep-linked scene with no animation, focus the column so
80|  // native keys scroll it, and pause narration follow on user input.
81|  useEffect(() => {
82|    const col = readColRef.current;
83|    if (!col) return;
84|    col.focus({ preventScroll: true });
85|    setCurrentSceneId(initialSceneId);
86|    scrollToSceneId(col, initialSceneId, false);
87|    return attachFollowPause(col);
88|  }, [initialSceneId]);
89|
90|  // The scene under the reading line (40% down the column) is current.
91|  // A thin rootMargin band, not ratios: a long scene filling the screen
92|  // must beat a short one fully in view, and the band fires exactly when
93|  // a section crosses the line. Ties keep document order. One observer,
94|  // no scroll listeners, no layout reads on scroll.
95|  useEffect(() => {
96|    const col = readColRef.current;
97|    if (!col) return;
98|    const seen = new Map<string, { id: string; ratio: number }>();
99|    const io = new IntersectionObserver(
100|      (entries) => {
101|        for (const entry of entries) {
102|          const id = (entry.target as HTMLElement).dataset.sceneId;
103|          if (!id) continue;
104|          if (entry.isIntersecting) seen.set(id, { id, ratio: entry.intersectionRatio });
105|          else seen.delete(id);
106|        }
107|        const next = pickCurrentScene(order, seen);
108|        if (next) commitScene(next);
109|      },
110|      { root: col, rootMargin: "-40% 0px -59% 0px", threshold: 0 },
111|    );
112|    for (const section of col.querySelectorAll("[data-scene-id]")) io.observe(section);
113|    return () => io.disconnect();
114|  }, [order, commitScene]);
115|
116|  // Chapter jumps from outside the column arrive here.
117|  useEffect(() => {
118|    const onGoto = (event: Event) => gotoScene((event as CustomEvent<string>).detail);
119|    window.addEventListener(GOTO_SCENE_EVENT, onGoto);
120|    return () => window.removeEventListener(GOTO_SCENE_EVENT, onGoto);
121|  }, [gotoScene]);
122|
123|  useEffect(() => {
124|    setStoredPref(loadImageStylePref());
125|  }, []);
126|
127|  function changePref(next: ImageStylePref) {
128|    setStoredPref(next);
129|    saveImageStylePref(next);
130|  }
131|
132|  const closePanels = useCallback(() => setPanelsCh(null), []);
133|
134|  const figsByN = useMemo(() => groupFiguresByEndN(pic.figures), [pic.figures]);
135|
136|  function gotoFigure(fig: InlineFigure) {
137|    const el = figEls.current.get(fig.id) ?? null;
138|    const col = readColRef.current;
139|    if (col) noteUserScroll(col);
140|    el?.scrollIntoView({ block: "nearest" });
141|    pulse(el);
142|  }
143|
144|  function gotoScenePicture() {
145|    const img = document.querySelector(".img-pane .pane-img");
146|    pulse(img instanceof HTMLElement ? img : null);
147|  }
148|
149|  function gotoScene(id: unknown) {
150|    if (typeof id !== "string") return;
151|    pic.hidePopover();
152|    const col = readColRef.current;
153|    if (col) scrollToSceneId(col, id, true);
154|  }
155|
156|  // A selection that starts in another scene moves the current scene
157|  // there; the popover follows without a second tap. Chapter headings and
158|  // the panels strip sit outside scene sections, so they never offer it.
159|  function onReadMouseUp() {
160|    const sel = window.getSelection();
161|    if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return;
162|    const node = sel.anchorNode;
163|    const el = node instanceof Element ? node : node?.parentElement ?? null;
164|    const section = el?.closest?.("[data-scene-id]") ?? null;
165|    const id = section instanceof HTMLElement ? section.dataset.sceneId : null;
166|    if (!id || id === currentId) return;
167|    commitScene(id);
168|    requestAnimationFrame(() => pic.rescan());
169|  }
170|
171|  return (
172|    <>
173|      <ImagePane
174|        card={pic.card}
175|        onPicture={() => pic.illustrateScene()}
176|        onRetry={() => pic.illustrateScene()}
177|        onClear={pic.clearScene}
178|        onOpen={pic.lightbox.open}
179|        onPictureChapter={info ? () => setPanelsCh(info.ch) : null}
180|      />
181|      <Divider />
182|      <div className="read-col" ref={readColRef} tabIndex={-1} aria-label="Reading column" onMouseUp={onReadMouseUp}>
183|        <ReadAlong columnRef={readColRef} />
184|        {model.chapters.map((chapter) => {
185|          const coverLong = coverTitleLong(chapter.title);
186|          return (
187|            <div className="chapter-block" key={chapter.ch}>
188|              <div className="kicker">Chapter</div>
189|              <p className="cover-num" data-long={coverLong} aria-label={`Chapter ${chapter.ch}`}>
190|                {chapter.ch}
191|              </p>
192|              <h1 className="chapter-title cover-title" data-long={coverLong}>
193|                {chapter.title}
194|              </h1>
195|              <hr className="cover-rule" />
196|              {chapter.scenes.map((s, si) => (
197|                <section
198|                  key={s.id}
199|                  className="book-section"
200|                  data-scene-id={s.id}
201|                  aria-label={s.title}
202|                  // Strings for the skin's `content:`; counters can't cross content-visibility.
203|                  style={
204|                    {
205|                      "--scene-n": `"${si + 1}"`,
206|                      "--scene-of": `" of ${chapter.scenes.length}"`,
207|                    } as CSSProperties
208|                  }
209|                >
210|                  <div
211|                    className={si === 0 ? "body-text dropcap" : "body-text"}
212|                    ref={s.id === currentId ? pic.viewRef : undefined}
213|                  >
214|                    {s.paragraphs.map((p, i, arr) => (
215|                      <Fragment key={p.id}>
216|                        <p id={p.id} data-n={p.n}>
217|                          {p.text}
218|                        </p>
219|                        {figuresAfter(arr, i, figsByN).map((fig) => (
220|                          <InlineFigureView
221|                            key={fig.id}
222|                            figure={fig}
223|                            onRemove={() => pic.removeFigure(fig.id)}
224|                            onRetry={() => pic.retryFigure(fig.id)}
225|                            onOpen={pic.lightbox.open}
226|                            refCb={(el) => {
227|                              if (el) figEls.current.set(fig.id, el);
228|                              else figEls.current.delete(fig.id);
229|                            }}
230|                          />
231|                        ))}
232|                      </Fragment>
233|                    ))}
234|                    {s.id === currentId && pic.popover !== null ? (
235|                      <SelectionPopover pos={pic.popover} popRef={pic.popRef} onPick={() => pic.illustratePassage()} />
236|                    ) : null}
237|                  </div>
238|                </section>
239|              ))}
240|              {chapter.ch === lastChapter ? (
241|                <p className="the-end">The end.</p>
242|              ) : (
243|                <div className="chapter-relive">
244|                  <button
245|                    type="button"
246|                    className="panels-link"
247|                    onClick={() => setPanelsCh(chapter.ch)}
248|                  >
249|                    Relive this chapter in panels
250|                  </button>
251|                </div>
252|              )}
253|            </div>
254|          );
255|        })}
256|      </div>
257|      <PictureVault
258|        scene={pic.card.phase === "ready" ? { url: pic.card.url, caption: pic.card.caption } : null}
259|        figures={pic.figures}
260|        onGotoScene={gotoScenePicture}
261|        onGotoFigure={gotoFigure}
262|        onOpen={pic.lightbox.open}
263|        pref={pref}
