109|async function poll(body: unknown): Promise<{ url: string; caption: string }> {
110|  let left = POLL_MAX;
111|  for (;;) {
112|    let res: ImageResponse;
113|    try {
114|      res = await postImage(body);
115|    } catch {
116|      throw new Error(MSG_FAILED);
117|    }
118|    if (res.status === "ready") return { url: res.url, caption: res.caption };
119|    if (res.status === "error") throw new Error(res.message);
120|    left -= 1;
121|    if (left <= 0) throw new Error(MSG_RETRY);
122|    await new Promise((done) => setTimeout(done, POLL_MS));
123|  }
