94|  // no scroll listeners, no layout reads on scroll.
95|  useEffect(() => {
96|    const col = readColRef.current;
97|    if (!col) return;
98|    const seen = new Map<string, { id: string; ratio: number }>();
99|    const io = new IntersectionObserver(
100|      (entries) => {
101|        for (const entry of entries) {
102|          const id = (entry.target as HTMLElement).dataset.sceneId;
103|          if (!id) continue;
104|          if (entry.isIntersecting) seen.set(id, { id, ratio: entry.intersectionRatio });
