1|import "server-only";
2|
3|// Reads image env once per request. Any missing key means unavailable:
4|// with no quotas or budget configured, the route must never spend.
5|export interface ImageEnv {
6|  upstashUrl: string;
7|  upstashToken: string;
8|  metaKey: string;
9|  sessionSecret: string;
10|  ipSalt: string;
11|  spendCapMicro: number;
12|  dailySpendCapMicro: number;
13|}
14|
15|// Vercel's Upstash marketplace integration injects KV_REST_API_* names.
16|// UPSTASH_* wins when non-empty, else the KV_* fallback applies per value.
17|// The read-only token is never used (we write).
18|const URL_NAMES = "UPSTASH_REDIS_REST_URL|KV_REST_API_URL";
19|const TOKEN_NAMES = "UPSTASH_REDIS_REST_TOKEN|KV_REST_API_TOKEN";
20|
21|// `vercel env pull` writes Sensitive vars as "[SENSITIVE]".
22|export function usable(raw: string | undefined): string | undefined {
23|  if (raw === undefined || raw === "") return undefined;
24|  if (/^\[[A-Z_]+\]$/.test(raw.trim())) return undefined;
25|  return raw;
26|}
27|
28|const REQUIRED = [
29|  "BLOB_READ_WRITE_TOKEN",
30|  "META_API_KEY",
31|  "SESSION_SECRET",
32|  "IP_HASH_SALT",
33|] as const;
34|
35|// One rule for both caps: a finite, non-negative USD value wins,
36|// anything else (missing, blank, non-numeric, negative, Infinity) falls back.
37|// Zero stays valid so a zero cap can intentionally block spend.
38|function parseCapUsd(raw: string | undefined, fallback: number): number {
39|  if (raw === undefined || raw.trim() === "") return fallback;
40|  const value = Number(raw);
41|  return Number.isFinite(value) && value >= 0 ? value : fallback;
42|}
43|
44|export function readImageEnv(from: NodeJS.ProcessEnv = process.env): ImageEnv {
45|  const upstashUrl = usable(from.UPSTASH_REDIS_REST_URL) ?? usable(from.KV_REST_API_URL);
46|  const upstashToken = usable(from.UPSTASH_REDIS_REST_TOKEN) ?? usable(from.KV_REST_API_TOKEN);
47|  // A non-https URL is a placeholder or typo, never a real endpoint.
48|  const url = upstashUrl?.startsWith("https://") ? upstashUrl : undefined;
49|  const missing = [
50|    url ? null : URL_NAMES,
51|    upstashToken ? null : TOKEN_NAMES,
52|    ...REQUIRED.filter((k) => !usable(from[k])),
53|  ].filter((m): m is string => m !== null);
54|  if (missing.length > 0) throw new Error(`missing image env: ${missing.join(",")}`);
55|  return {
56|    upstashUrl: url as string,
57|    upstashToken: upstashToken as string,
58|    metaKey: from.META_API_KEY as string,
59|    sessionSecret: from.SESSION_SECRET as string,
60|    ipSalt: from.IP_HASH_SALT as string,
61|    spendCapMicro: Math.round(parseCapUsd(from.SPEND_CAP_USD, 10) * 1_000_000),
62|    dailySpendCapMicro: Math.round(parseCapUsd(from.DAILY_SPEND_CAP_USD, 2) * 1_000_000),
63|  };
64|}

