1|import "server-only";
2|import type { KV } from "@/core/images";
3|
4|// Upstash REST client over built-in fetch. Single commands only, no
5|// pipeline: the route issues few calls and a helper would add lines.
6|export function createRestKV(url: string, token: string): KV {
7|  async function cmd<T>(args: (string | number)[]): Promise<T> {
8|    const res = await fetch(url, {
9|      method: "POST",
10|      headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
11|      body: JSON.stringify(args),
12|      signal: AbortSignal.timeout(5_000),
13|    });
14|    if (!res.ok) throw new Error(`kv status ${res.status}`);
15|    const json = (await res.json()) as { result?: T; error?: string };
16|    if (json.error !== undefined) throw new Error("kv error");
17|    return json.result as T;
18|  }
19|  return {
20|    get: (key) => cmd<string | null>(["GET", key]),
21|    setNxEx: async (key, value, exSec) =>
22|      (await cmd<string | null>(["SET", key, value, "NX", "EX", exSec])) === "OK",
23|    set: async (key, value) => {
24|      await cmd(["SET", key, value]);
25|    },
26|    incr: (key) => cmd<number>(["INCR", key]),
27|    incrBy: (key, by) => cmd<number>(["INCRBY", key, by]),
28|    decr: (key) => cmd<number>(["DECR", key]),
29|    decrBy: (key, by) => cmd<number>(["DECRBY", key, by]),
30|    expire: async (key, sec) => {
31|      await cmd(["EXPIRE", key, sec]);
32|    },
33|    // Lua compare-and-delete: an expired lock must not free a new owner.
34|    releaseIfToken: async (key, tokenValue) =>
35|      (await cmd<number>([
36|        "EVAL",
37|        'if redis.call("GET",KEYS[1])==ARGV[1] then return redis.call("DEL",KEYS[1]) else return 0 end',
38|        1,
39|        key,
40|        tokenValue,
41|      ])) === 1,
42|  };
43|}

