49|// hackathon. Keys carry no day so the limit never resets; the TTL (~10
50|// days) only bounds Redis growth. No route or wiring yet, just the hook.
51|export const FREE_BOOKS_PER_PERSON = 1;
52|export const BOOK_QUOTA_TTL_SEC = 10 * 24 * 3600;
53|
54|export function bookQuotaKeys(args: { ipHash: string; anonId: string }): {
55|  ip: string;
56|  anon: string;
57|} {
